const useNotificationStore = create((set) => ({
  notifications: [],
  unreadCount: 0,
  addNotification: (notification) => {
    const newNotification = {
      ...notification,
      id: crypto.randomUUID(),
      timestamp: Date.now(),
      read: false
    };
    set((state) => ({
      notifications: [newNotification, ...state.notifications],
      unreadCount: state.unreadCount + 1
    }));
  },
  markAsRead: (id) => {
    set((state) => ({
      notifications: state.notifications.map((n2) => n2.id === id ? { ...n2, read: true } : n2),
      unreadCount: Math.max(0, state.unreadCount - 1)
    }));
  },
  markAllAsRead: () => {
    set((state) => ({
      notifications: state.notifications.map((n2) => ({ ...n2, read: true })),
      unreadCount: 0
    }));
  },
  removeNotification: (id) => {
    set((state) => {
      const notification = state.notifications.find((n2) => n2.id === id);
      return {
        notifications: state.notifications.filter((n2) => n2.id !== id),
        unreadCount: notification && !notification.read ? state.unreadCount - 1 : state.unreadCount
      };
    });
  },
  clearAll: () => {
    set({ notifications: [], unreadCount: 0 });
  }
}));
